def authenticate_api_key(db: Session, raw_key: str | None) -> ApiKey:
    if not raw_key:
        raise HTTPException(status_code=401, detail="API key required")
    key = db.scalar(select(ApiKey).where(ApiKey.key_prefix == raw_key[:16], ApiKey.is_active.is_(True)).options(selectinload(ApiKey.owner)))
    if not key or not hmac_compare(hash_token(raw_key), key.key_hash):
        raise HTTPException(status_code=401, detail="Invalid API key")
    key.last_used_at = utcnow()
    return key
